class EmptyLineTracker:
    """
    Provides a stateful method that returns the number of potential extra empty lines needed before and after the currently processed line.

    This tracker works on lines that haven't been split yet. It assumes the prefix of the first leaf consists of optional newlines, which are consumed by `maybe_empty_lines()` and included in the computation.

    Parameters:
        current_line (Line): The current line being processed. This object contains information about whether the line is a decorator, class, function, or comment, as well as its depth within the code structure.
        before (int): An integer indicating the number of empty lines expected before the current line. If `before` is 0, it means no additional empty lines are needed before the current line.

    Returns:
        Tuple[int, int]: A tuple containing two integers. The first integer represents the number of potential extra empty lines needed before the current line, and the second integer represents the number of potential extra empty lines needed after the current line.

    Examples:
        To use this function effectively, ensure that you pass a `Line` object representing the current line being processed to the function. The `before` parameter should be set according to your specific requirements for handling empty lines before and after the current line.

    Notes:
        - This tracker does not insert empty lines before the first line in the file.
        - It ignores potential empty lines if the previous line is a decorator or if both the current and previous lines are at the same depth but the previous line is a comment.
        - The function handles special cases for classes, functions, and comments differently depending on whether it's processing Python interface (`.pyi`) files.
    """
    is_pyi: bool = False
    previous_line: Optional[Line] = None
    previous_after: int = 0
    previous_defs: List[int] = field(default_factory=list)

    def _maybe_empty_lines_for_class_or_def(self, current_line: Line, before: int) -> Tuple[int, int]:
        if not current_line.is_decorator:
            self.previous_defs.append(current_line.depth)
        if self.previous_line is None:
            # Don't insert empty lines before the first line in the file.
            return 0, 0

        if self.previous_line.is_decorator:
            return 0, 0

        if self.previous_line.depth < current_line.depth and (self.previous_line.is_class or self.previous_line.is_def):
            return 0, 0

        if self.previous_line.is_comment and self.previous_line.depth == current_line.depth and before == 0:
            return 0, 0

        if self.is_pyi:
            if self.previous_line.depth > current_line.depth:
                newlines = 1
            elif current_line.is_class or self.previous_line.is_class:
                if current_line.is_stub_class and self.previous_line.is_stub_class:
                    # No blank line between classes with an empty body
                    newlines = 0
                else:
                    newlines = 1
            elif current_line.is_def and not self.previous_line.is_def:
                # Blank line between a block of functions and a block of non-functions
                newlines = 1
            else:
                newlines = 0
        else:
            newlines = 2
        if current_line.depth and newlines:
            newlines -= 1
        return newlines, 0
